import json, itertools

with open('/app/puzzles.json') as f:
    puzzles = json.load(f)

# Let's test all combinations of:
# ⊕ in {a+b+1} (fixed by P6, P8? wait - let's allow a+b+1, a+b+i, a+b+d+1, a+b+n-1 too)
# ⊗ in {a*b-1, a*b-i, a*b-d-1}
# ⊞ in {a+b, a+b+d, a+b+i-1, a+b+n-2}
# ⊠ in {a+b+n, a+b+i+1}
# ◇ in {max(a,b), max(a,b)+d}

# Actually let's test pairs of deviations from ops_base first!
ops_base = {
    "⊕": ("a+b+1", lambda a, b, n, i, d: a + b + 1),
    "⊗": ("a*b-1", lambda a, b, n, i, d: a * b - 1),
    "◇": ("max(a,b)", lambda a, b, n, i, d: max(a, b)),
    "▽": ("abs(a-b)", lambda a, b, n, i, d: abs(a - b)),
    "⊘": ("2*a-b", lambda a, b, n, i, d: 2 * a - b),
    "⊛": ("a+b**2", lambda a, b, n, i, d: a + b ** 2),
    "⊞": ("a+b", lambda a, b, n, i, d: a + b),
    "⊠": ("a+b+n", lambda a, b, n, i, d: a + b + n),
    "△": ("max(0,a-b)", lambda a, b, n, i, d: max(0, a - b)),
}

# What if we check ALL expressions for P1, P3, P7 that are within +-3 of target under ops_base?
# No, wait: let's check what happens if ⊞ is a+b vs a+b+d vs a+b+i-1 vs a+b+n-2, AND ⊗ is a*b-1 vs a*b-i, AND ◇ is max(a,b) vs max(a,b)+d.
alts = {
    "⊕": [("a+b+1", lambda a,b,n,i,d: a+b+1), ("a+b+i", lambda a,b,n,i,d: a+b+i), ("a+b+d+1", lambda a,b,n,i,d: a+b+d+1)],
    "⊗": [("a*b-1", lambda a,b,n,i,d: a*b-1), ("a*b-i", lambda a,b,n,i,d: a*b-i)],
    "⊞": [("a+b", lambda a,b,n,i,d: a+b), ("a+b+d", lambda a,b,n,i,d: a+b+d), ("a+b+i-1", lambda a,b,n,i,d: a+b+i-1), ("a+b+n-2", lambda a,b,n,i,d: a+b+n-2)],
    "◇": [("max(a,b)", lambda a,b,n,i,d: max(a,b)), ("max(a,b)+d", lambda a,b,n,i,d: max(a,b)+d)],
}

def count_solved(m):
    res = {}
    for pk, pv in puzzles.items():
        a0, a1, a2, a3 = pv["numbers"]
        t = pv["target"]
        c = 0
        op_names = list(m.keys())
        for o1, o2, o3 in itertools.product(op_names, repeat=3):
            f1, f2, f3 = m[o1][1], m[o2][1], m[o3][1]
            if f3(f2(f1(a0, a1, 4, 1, 2), a2, 4, 2, 1), a3, 4, 3, 0) == t: c += 1
            if f3(f1(a0, f2(a1, a2, 4, 2, 2), 4, 1, 1), a3, 4, 3, 0) == t: c += 1
            if f1(a0, f3(f2(a1, a2, 4, 2, 2), a3, 4, 3, 1), 4, 1, 0) == t: c += 1
            if f1(a0, f2(a1, f3(a2, a3, 4, 3, 2), 4, 2, 1), 4, 1, 0) == t: c += 1
            if f2(f1(a0, a1, 4, 1, 1), f3(a2, a3, 4, 3, 1), 4, 2, 0) == t: c += 1
        if c > 0:
            res[pk] = c
    return res

for oplus in alts["⊕"]:
    for otimes in alts["⊗"]:
        for bplus in alts["⊞"]:
            for diam in alts["◇"]:
                m = dict(ops_base)
                m["⊕"] = oplus
                m["⊗"] = otimes
                m["⊞"] = bplus
                m["◇"] = diam
                res = count_solved(m)
                if len(res) >= 6:
                    print(f"⊕={oplus[0]:7s} ⊗={otimes[0]:5s} ⊞={bplus[0]:7s} ◇={diam[0]:10s} -> {len(res)}: {res}")
EOF
